import gurobipy as gp
from gurobipy import GRB

def solve_supply_chain():
    S = ['S1', 'S2', 'S3', 'S4', 'S5', 'S6', 'S7', 'S8', 'S9', 'S10', 'S11', 'S12']
    C = ['C1', 'C2', 'C3', 'C4', 'C5', 'C6', 'C7', 'C8', 'C9', 'C10', 'C11', 'C12']
    demand = {'C1': 52, 'C2': 80, 'C3': 392, 'C4': 103, 'C5': 32, 'C6': 1426, 'C7': 1024, 'C8': 2736, 'C9': 1129, 'C10': 676, 'C11': 2631, 'C12': 31}
    supply = {'S1': 58, 'S2': 32, 'S3': 6161, 'S4': 4, 'S5': 47, 'S6': 178, 'S7': 142, 'S8': 164, 'S9': 1011, 'S10': 6, 'S11': 7081, 'S12': 948}
    cost = {'S1': {'C1': 134.72882437877243, 'C2': 72.30045141110347, 'C3': 37.9759927355347, 'C4': 611.84656497826, 'C5': 1650.3353902326157, 'C6': 32.97044486689555, 'C7': 34.99837373425947, 'C8': 73.25207370031997, 'C9': 165.752089835103, 'C10': 82.52035827662691, 'C11': 1538.830198350349, 'C12': 2320.1146477101956}, 'S2': {'C1': 23.835369186583733, 'C2': 1128.6332865368709, 'C3': 187.05459590556023, 'C4': 1.6077337129635412, 'C5': 2227.7036991312493, 'C6': 72.44693148708649, 'C7': 12.60074797346823, 'C8': 1078.7729548111274, 'C9': 383.7220569377865, 'C10': 82.8115250443967, 'C11': 1702.1724763823142, 'C12': 1925.8446970545492}, 'S3': {'C1': 1138.498759622659, 'C2': 231.8983422482863, 'C3': 44.1568226726957, 'C4': 962.5481640749796, 'C5': 980.1306032437444, 'C6': 1107.5157506568996, 'C7': 741.7073424442746, 'C8': 136.70204401709762, 'C9': 1182.5161115443857, 'C10': 664.1846792537777, 'C11': 36.70238978444623, 'C12': 1405.0506919253128}, 'S4': {'C1': 1043.7562803117191, 'C2': 24.207016063238527, 'C3': 1120.9890438994094, 'C4': 1027.5437638768522, 'C5': 893.4457577903337, 'C6': 1244.2626779205734, 'C7': 980.0297707948428, 'C8': 513.5650272201696, 'C9': 977.6321548115833, 'C10': 642.5520451224766, 'C11': 437.9556823253786, 'C12': 76.12498668603241}, 'S5': {'C1': 4.939930661779214, 'C2': 1278.1815735383598, 'C3': 549.7570743190075, 'C4': 21.335474111511868, 'C5': 98.32689279702352, 'C6': 452.0903462786745, 'C7': 595.5981933612871, 'C8': 70.84029746549007, 'C9': 0.001236242263106387, 'C10': 1783.0865677438942, 'C11': 1619.6154655942953, 'C12': 116.08497905117572}, 'S6': {'C1': 2105.5398596409113, 'C2': 1340.9770559580859, 'C3': 2077.2747284488696, 'C4': 2202.2515396165613, 'C5': 20.5336958780729, 'C6': 2514.0983598337716, 'C7': 2393.213466538681, 'C8': 1197.765543404598, 'C9': 102.32440248566687, 'C10': 788.4640306393768, 'C11': 818.9532260267922, 'C12': 17.249645794282493}, 'S7': {'C1': 61.36183063260923, 'C2': 113.23716964851326, 'C3': 50.231076475261865, 'C4': 1219.1951077346878, 'C5': 869.868986439361, 'C6': 58.3717723017115, 'C7': 957.3213131437595, 'C8': 168.9964798230943, 'C9': 1363.342713601386, 'C10': 519.3858364273143, 'C11': 483.3345987058458, 'C12': 1412.7652882009972}, 'S8': {'C1': 1169.3640988900754, 'C2': 1037.2170744709088, 'C3': 732.3577706907058, 'C4': 865.2255769415611, 'C5': 1510.0296187049466, 'C6': 780.853789775776, 'C7': 860.7971696230202, 'C8': 935.9126432821531, 'C9': 61.82504909829045, 'C10': 72.78392607232098, 'C11': 1479.1137195486635, 'C12': 65.87463475119084}, 'S9': {'C1': 7.936521667214095, 'C2': 1357.5387610434743, 'C3': 628.3001825422914, 'C4': 25.245141819018265, 'C5': 1760.0085249934855, 'C6': 604.6583535734275, 'C7': 696.677483277236, 'C8': 1586.4093183806565, 'C9': 89.68006942976479, 'C10': 1580.7262556456867, 'C11': 1423.5615412405277, 'C12': 2000.5637996766272}, 'S10': {'C1': 1685.3409758586952, 'C2': 437.39384912973503, 'C3': 1568.8939936485654, 'C4': 1486.9268967582923, 'C5': 498.37544466423503, 'C6': 1493.3860214089566, 'C7': 70.17952878640685, 'C8': 526.999992252258, 'C9': 1527.6606596831157, 'C10': 2.676413573774264, 'C11': 202.72671236450077, 'C12': 45.95308313010429}, 'S11': {'C1': 937.1094078301182, 'C2': 903.0141415848653, 'C3': 264.7208998642393, 'C4': 21.823340175910644, 'C5': 1661.105486348982, 'C6': 18.59349093795307, 'C7': 372.0817876391536, 'C8': 956.6955598743717, 'C9': 42.9120185256587, 'C10': 1274.3227526636908, 'C11': 1574.7961500081667, 'C12': 1826.428257280374}, 'S12': {'C1': 1685.7576850724427, 'C2': 377.3256672852414, 'C3': 1347.0162725120726, 'C4': 1737.020030508406, 'C5': 23.612177980608287, 'C6': 83.08521829288628, 'C7': 1476.1258241571823, 'C8': 530.0021927141197, 'C9': 1782.8442633270377, 'C10': 0.010486218015015225, 'C11': 11.1693204455916, 'C12': 963.9941814871104}}
    for s in S:
        if s not in cost:
            raise ValueError(f'Missing cost data for supply {s}')
        for c in C:
            if c not in cost[s]:
                raise ValueError(f'Missing cost data for supply {s}, customer {c}')
    for c in C:
        if c not in demand:
            raise ValueError(f'Missing demand data for customer {c}')
    for s in S:
        if s not in supply:
            raise ValueError(f'Missing supply data for supply {s}')
    m = gp.Model()
    m.Params.MIPGap = 0.0001
    x = m.addVars(S, C, lb=0, vtype=GRB.CONTINUOUS, name='')
    obj = gp.LinExpr()
    for s in S:
        for c in C:
            obj += cost[s][c] * x[s, c]
    m.setObjective(obj, GRB.MINIMIZE)
    for c in C:
        m.addConstr(gp.quicksum((x[s, c] for s in S)) == demand[c], name='')
    for s in S:
        m.addConstr(gp.quicksum((x[s, c] for c in C)) <= supply[s], name='')
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print(f'ObjVal {m.ObjVal}')
        for s in S:
            for c in C:
                v = x[s, c]
                print(f'{v.VarName} {v.X}')
    else:
        print(f'Solver status: {m.Status}')
    return m
m = solve_supply_chain()